#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

// 独立推导：按位恒等式 (x&y)+(x|y) == x+y，故最小正整数解 y = 2025 - x
static int expected(int x) { return 2025 - x; }

static bool check(const string& exe, int x, int id) {
    const string inFile = "l3a03p1_input.txt", outFile = "l3a03p1_output.txt";
    { ofstream out(inFile); out << x << '\n'; }
    string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    string output((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    istringstream parser(output);
    int actual = -12345;
    string extra;
    const int want = expected(x);
    bool ok = code == 0 && (parser >> actual) && !(parser >> extra) && actual == want;
    if (!ok) {
        cout << "[FAIL] case " << id << ": x=" << x << ", expected=" << want
             << ", actual=" << output.substr(0, 120) << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<int> tests = {1025, 0, 2024, 1, 1012, 2000, 999, 1024, 1026 % 2025, 333};
    unsigned seed = 202503u;
    for (int trial = 0; trial < 8; ++trial) {
        seed = seed * 1664525u + 1013904223u;
        tests.push_back(static_cast<int>(seed % 2025u));
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i], static_cast<int>(i+1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}

