#include <algorithm>
#include <cctype>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <sstream>
#include <string>
#include <utility>
#include <vector>
using namespace std;

static string lower(string s) {
    for (size_t i = 0; i < s.size(); ++i)
        s[i] = static_cast<char>(tolower(static_cast<unsigned char>(s[i])));
    return s;
}

// 独立实现：用 vector<pair> 线性扫描计数（不复用 map），返回出现次数最多的单词（小写）
static string expected(const vector<string>& words) {
    vector<pair<string, int> > cnt;
    for (size_t i = 0; i < words.size(); ++i) {
        string w = lower(words[i]);
        bool found = false;
        for (size_t j = 0; j < cnt.size(); ++j)
            if (cnt[j].first == w) { cnt[j].second++; found = true; break; }
        if (!found) cnt.push_back(make_pair(w, 1));
    }
    string best; int bestc = -1;
    for (size_t j = 0; j < cnt.size(); ++j)
        if (cnt[j].second > bestc) { bestc = cnt[j].second; best = cnt[j].first; }
    return best;
}

static bool check(const string& exe, const vector<string>& words, int id) {
    const string inFile = "l3a03p2_input.txt", outFile = "l3a03p2_output.txt";
    {
        ofstream out(inFile);
        out << words.size() << '\n';
        for (size_t i = 0; i < words.size(); ++i) out << words[i] << '\n';
    }
    string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    string output((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    istringstream parser(output);
    string actual;
    string extra;
    const string want = expected(words);
    bool ok = code == 0 && (parser >> actual) && !(parser >> extra) && actual == want;
    if (!ok) {
        cout << "[FAIL] case " << id << ": n=" << words.size() << ", expected=" << want
             << ", actual=" << output.substr(0, 120) << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<vector<string> > tests;
    {
        vector<string> t;
        t.push_back("Apple"); t.push_back("banana"); t.push_back("apple");
        t.push_back("Orange"); t.push_back("banana"); t.push_back("apple");
        tests.push_back(t);
    }
    { vector<string> t; t.push_back("Zz"); tests.push_back(t); }
    {
        vector<string> t;
        for (int i = 0; i < 7; ++i) t.push_back(i % 2 ? "MiXeD" : "mixed");
        t.push_back("other");
        tests.push_back(t);
    }
    {
        vector<string> t;
        t.push_back("aaa"); t.push_back("AAA"); t.push_back("aAa");
        t.push_back("bbb"); t.push_back("BBB");
        tests.push_back(t);
    }
    {
        vector<string> t(30, string(30, 'W'));
        t.push_back(string(30, 'w'));
        tests.push_back(t);
    }
    {
        vector<string> t;
        t.push_back("cat"); t.push_back("dog"); t.push_back("cat");
        t.push_back("dog"); t.push_back("cat"); t.push_back("bird");
        tests.push_back(t);
    }
    unsigned seed = 202503u;
    for (int trial = 0; trial < 5; ++trial) {
        vector<string> t;
        for (int i = 0; i < 99; ++i) {
            seed = seed * 1664525u + 1013904223u;
            int len = 1 + static_cast<int>(seed % 30u);
            string w;
            for (int c = 0; c < len; ++c) {
                seed = seed * 1664525u + 1013904223u;
                w += static_cast<char>('a' + seed % 26u);
            }
            seed = seed * 1664525u + 1013904223u;
            if (seed % 2u)
                for (size_t k = 0; k < w.size(); k += 2)
                    w[k] = static_cast<char>(toupper(static_cast<unsigned char>(w[k])));
            t.push_back(w);
        }
        // 保证最高频唯一：再追加一个当前最高频单词，使其次数严格超过其余单词
        t.push_back(expected(t));
        tests.push_back(t);
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i], static_cast<int>(i+1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}
